std::optional<int> parseNumericInput(void);

class BFTask {
public:
  BFTask(int id, unsigned short tapeSize, bool doBackup)
      : _id(id), tape(tapeSize, 0), sql_query(sql_select),
        instructionPointer(0), dataPointer(0), doBackup(doBackup) {}

