    if (sqlite3_exec(db, sql_query.c_str(), _backup_callback, 0,
                     &_sqlite3ErrMsg) != SQLITE_OK)
      throw std::runtime_error(std::string("sqlite3_exec: ") + _sqlite3ErrMsg);
  }

